(28, '0x0104', 'pair_action', 'empty', NULL, NULL, NULL, NULL, 'Pairing transaction marker in POST .../pair; present on both start and stop', NULL),
(29, '0x01a0', 'fw_state_status', 'u8', 'enum', NULL, NULL, NULL, 'Firmware state/status byte seen in d/<dev>/fw.state. Observed: 0x07 immediately before an update sequence; 0x08 when device is on normal/steady state after update.', NULL),
(30, '0x003a', 'fw_version_active', 'u16be', 'version_fp6', NULL, NULL, NULL, 'Active/running firmware version.', NULL),
(31, '0x0039', 'fw_version_target_or_reported', 'u16be', 'version_fp6', NULL, NULL, NULL, 'Second firmware version field in fw.state. Often matches 0x003A after update; can be 0x0000 before update. Likely \'target/expected\' or \'reported-to-cloud\' firmware version.', NULL),
(32, '0x0035', 'fw_version_other_slot', 'u16be', 'version_fp6', NULL, NULL, NULL, 'Firmware version present in the other/inactive external SPI slot (or previous version).', NULL),
(33, '0x003b', 'fw_state_phase_or_step', 'u8', 'enum_or_u8', NULL, NULL, NULL, 'Small state/phase value in fw.state. Observed values: 0x0E (older state) and 0x06 (post-update). Likely update/bootloader phase indicator.', NULL),
(34, '0x0036', 'fw_state_aux_0036', 'u8', 'u8', NULL, NULL, NULL, 'Auxiliary fw.state byte. Observed: VA/RU show 0x0A; IB shows 0x00. Possibly device-family, channel, or partition indicator. Needs more samples correlated with device type.', NULL),
(35, '0x003c', 'fw_state_phase_aux_003c', 'u8', 'enum_or_u8', NULL, NULL, NULL, 'Second small state/phase value in fw.state. Observed values track 0x003B in samples (e.g., 0x0E or 0x06). Likely additional phase/health indicator for the update state machine.', NULL),
(36, '0x0180', 'fw_state_update_result_or_bootcount', 'u8', 'u8_or_enum', NULL, NULL, NULL, 'fw.state flag that changed across an update in observed VA: 0x00 before update, 0x04 after update. Likely update result/status, applied-update marker, or boot counter/flags.', NULL),
(37, '0x012d', 'temperature_ambient', 's16be', 'C', 0.01, 2, NULL, 'Primary ambient temperature (°C×100). | Seen in: d/RU*/sen, d/VA*/sen | Len: 2 bytes | u16 values around 1600–1900 consistent with temperature in centi-degrees (°C×100).', NULL),
(38, '0x012e', 'aux_temperature_1', 's16be', 'C', 0.01, 2, NULL, 'Secondary temperature (°C×100). | Seen in: d/RU*/sen, d/VA*/sen | Len: 2 bytes | u16 values around 1600–1900 consistent with temperature in centi-degrees (°C×100).', NULL),
(39, '0x0135', 'humidity_percent', 'u16be', '%', 0.1, 1, NULL, 'Relative humidity (%×10). | Seen in: d/RU*/sen, d/VA*/sen | Len: 2 bytes | u16 values around 450–560 consistent with humidity ×10 (%RH).', NULL),
(40, '0x0136', 'ambient_light_level', 'u8', 'level', NULL, NULL, NULL, 'Ambient light level (unitless). | Seen in: d/RU*/sen, d/VA*/sen | Len: 1 bytes | u8 values 0–70-ish; likely ambient light \'level\'.', NULL),
(41, '0x0137', 'dial_encoder_steps', 'u8', 'step', NULL, NULL, NULL, 'Dial encoder A/B state bitfield (0..3 typical). | Seen in: d/RU*/sen, d/VA*/sen | Observed values: 0, 3 | Len: 1 bytes | u8 values 0–3-ish; likely dial encoder A/B state bitfield.', NULL),
